// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testRegression_property() public {
        uint256 balBefore = address(c).balance;
        vm.deal(address(c), 1 wei);
        bool ok;
        try c.sendTo(address(0), 1) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore + 1 wei, "Reference should revert, leaving balance unchanged");
    }
}
